public class Drill {
    static List<String> rateLimit(int[] ts, String[] cl, int limit, int window) {
        Map<String, Deque<Integer>> m = new HashMap<>();
        List<String> out = new ArrayList<>();
        for (int i = 0; i < ts.length; i++) {
            Deque<Integer> q = m.computeIfAbsent(cl[i], k -> new ArrayDeque<>());
            while (!q.isEmpty() && q.peekFirst() <= ts[i] - window) q.pollFirst();
            if (q.size() < limit) {
                q.addLast(ts[i]);
                out.add("ALLOW");
            } else {
                out.add("DENY");
            }
        }
        return out;
    }

    static int bad = 0;
    static void check(Object got, Object exp) {
        String g = String.valueOf(got), e = String.valueOf(exp);
        if (!g.equals(e)) { bad++; System.out.println("FAIL: got " + g + " expected " + e); }
    }
    static void done() { if (bad == 0) System.out.println("PASS"); }

    public static void main(String[] args) {
        check(rateLimit(new int[]{1, 2, 3, 11, 12, 12}, new String[]{"a", "a", "a", "a", "a", "b"}, 2, 10),
              "[ALLOW, ALLOW, DENY, ALLOW, ALLOW, ALLOW]");
        check(rateLimit(new int[]{1, 1}, new String[]{"a", "a"}, 0, 5), "[DENY, DENY]");
        done();
    }
}

